import sys

def main():
    d = sys.stdin.read().split()
    if not d:
        return
    n, t = int(d[0]), int(d[1])
    nums = [int(x) for x in d[2:n+2]]
    seen = {}
    for i, x in enumerate(nums):
        if (t - x) in seen:
            print(f"{seen[t - x]} {i}")
            return
        seen[x] = i

if __name__ == "__main__":
    main()
